const finalResults = [];

for (const inputItem of $input.all()) {
    try {
        const itemJson = inputItem.json;
        // ดึงข้อความดิบจาก Gemini Output
        let rawText = itemJson.content?.parts?.[0]?.text || itemJson.text || '';
        // ลบ markdown code blocks ออก
        let cleanJsonText = String(rawText).replace(/```json\s*|```\s*/g, "").trim();

        let parsedData = JSON.parse(cleanJsonText);
        // รองรับทั้งแบบส่งกลับมาเป็น { results: [] } หรือ [] ตรงๆ
        let resultsArray = parsedData.results || (Array.isArray(parsedData) ? parsedData : [parsedData]);

        for (const item of resultsArray) {
            // 1. ล้าง fingerprint ให้สะอาดที่สุด (ลบขึ้นบรรทัดใหม่และช่องว่าง)
            const cleanFingerprint = String(item.fingerprint || '').replace(/\n/g, '').trim();

            // 2. จัดการ keyword_painpoint: บีบให้เป็น String บรรทัดเดียวเสมอ
            let rawPainpoint = item.keyword_painpoint || item.pain_points || '';
            let cleanPainpoint = Array.isArray(rawPainpoint) 
                ? rawPainpoint.join(', ') // ถ้ามาเป็น Array ให้เชื่อมด้วยคอมม่า
                : String(rawPainpoint).replace(/\n/g, ' ').trim(); // ถ้ามาเป็น String ให้ลบการขึ้นบรรทัดใหม่

            // 3. คำนวณ KD Number (Logic เดิมของพี่)
            const kd = (item.qualitative_kd || '').toLowerCase();
            let kdNum = 0;
            if (kd.includes('very hard')) kdNum = 99;
            else if (kd.includes('hard')) kdNum = 84;
            else if (kd.includes('possible')) kdNum = 49;
            else if (kd.includes('easy')) kdNum = 29;
            else if (kd.includes('very easy')) kdNum = 15; // แถมกรณี Very Easy ให้ครับ

            // 4. ประกอบร่างข้อมูล (ป้องกัน undefined ในทุกฟิลด์สำคัญ)
            finalResults.push({
                json: {
                    ...item, // กระจายค่าเดิม
                    fingerprint: cleanFingerprint,
                    keyword_painpoint: cleanPainpoint,
                    keyword_core_insight: String(item.keyword_core_insight || '').replace(/\n/g, ' ').trim(),
                    kd_reasoning: String(item.kd_reasoning || '').replace(/\n/g, ' ').trim(),
                    qualitative_kd_number: kdNum,
                    // กำหนดวันเวลาปัจจุบันสำหรับบันทึกลง DB
                    keyword_contextual_ready_last_update: new Date().toISOString()
                }
            });
        }
    } catch (e) {
        // กรณี Error ให้ส่งข้อมูลที่ช่วยให้ Debug ได้ง่ายขึ้น
        finalResults.push({ 
            json: { 
                fingerprint: 'ERROR_PARSING', 
                error: e.message,
                raw_text_preview: String(inputItem.json.text || '').substring(0, 100)
            } 
        });
    }
}

return finalResults;
